function u(n){return`₦${Number(n||0).toLocaleString("en-NG")}`}function s(n,e={}){var r;const i=Number(n||0),a=(r=e.maximumFractionDigits)!=null?r:2,t=i.toFixed(a);return`${t.indexOf(".")>=0?t.replace(/\.?0+$/,""):t}L`}function o(n,e={}){return s(n,e).slice(0,-1)}function m(n,e={}){return Number(n||0).toLocaleString("en-NG",e)}function l(n){return(n||"U").split(" ").map(e=>e[0]||"").join("").slice(0,2).toUpperCase()}function f(n){return n?n==="gm"?"General Manager":n.charAt(0).toUpperCase()+n.slice(1):"—"}export{o as a,m as b,l as i,s as l,u as n,f as r};
